#!/bin/bash

# Generate Go types from HashPost custom lexicons
# This script generates Go structs from the lexicon JSON files

set -e

echo "Generating Go types from HashPost lexicons..."

# Create the generated directory if it doesn't exist
mkdir -p internal/lexicons/generated

# Generate Go types from the lexicon JSON
# For now, we'll create a simple Go file with the types
# In the future, this could use a proper lexicon code generator

cat > internal/lexicons/generated/types.go << 'EOF'
// Code generated by scripts/generate-lexicons.sh. DO NOT EDIT.

package generated

import "time"

// HashPostFeedPost represents a HashPost feed post record
type HashPostFeedPost struct {
	Type      string    `json:"$type"`      // Always "com.hashpost.feed.post"
	Text      string    `json:"text"`       // Post content (max 3000 chars)
	CreatedAt time.Time `json:"createdAt"` // ISO 8601 timestamp
	Reply     *Reply    `json:"reply,omitempty"`     // Optional reply information
	Embed     *Embed    `json:"embed,omitempty"`     // Optional embed information
}

// Reply represents reply information for a post
type Reply struct {
	Root   string `json:"root,omitempty"`   // Root post URI
	Parent string `json:"parent,omitempty"` // Parent post URI
}

// Embed represents embedded content in a post
type Embed struct {
	Type string `json:"type"`           // "image", "link", or "quote"
	URL  string `json:"url,omitempty"`  // Embed URL
	Alt  string `json:"alt,omitempty"`  // Alt text for images
}

// HashPostForumSubforum represents a HashPost forum subforum
type HashPostForumSubforum struct {
	Type        string    `json:"$type"`        // Always "com.hashpost.forum.subforum"
	Name        string    `json:"name"`         // Subforum name (max 100 chars)
	Slug        string    `json:"slug"`         // URL slug (alphanumeric + hyphens)
	Description string    `json:"description"`  // Subforum description (max 500 chars)
	CreatedAt   time.Time `json:"createdAt"`   // ISO 8601 timestamp
}

// HashPostFeedComment represents a HashPost feed comment record
type HashPostFeedComment struct {
	Type      string    `json:"$type"`      // Always "com.hashpost.feed.comment"
	Text      string    `json:"text"`       // Comment content (max 3000 chars)
	Post      string    `json:"post"`       // AT-URI of the post this comment belongs to
	Parent    string    `json:"parent,omitempty"` // AT-URI of parent comment for nested replies
	CreatedAt time.Time `json:"createdAt"` // ISO 8601 timestamp
}

// Constants for HashPost lexicon types
const (
	// Record types
	RecordTypeHashPostFeedPost     = "com.hashpost.feed.post"
	RecordTypeHashPostForumSubforum = "com.hashpost.forum.subforum"
	RecordTypeHashPostFeedComment  = "com.hashpost.feed.comment"
	
	// Collection names
	CollectionHashPostFeedPost     = "com.hashpost.feed.post"
	CollectionHashPostForumSubforum = "com.hashpost.forum.subforum"
	CollectionHashPostFeedComment  = "com.hashpost.feed.comment"
	
	// Field names
	FieldText        = "text"
	FieldCreatedAt   = "createdAt"
	FieldName        = "name"
	FieldSlug        = "slug"
	FieldDescription = "description"
	FieldReply       = "reply"
	FieldEmbed       = "embed"
	FieldPost        = "post"
	FieldParent      = "parent"
	
	// Embed types
	EmbedTypeImage = "image"
	EmbedTypeLink  = "link"
	EmbedTypeQuote = "quote"
)

// ValidateHashPostFeedPost validates a HashPost feed post record
func ValidateHashPostFeedPost(post *HashPostFeedPost) error {
	if post.Type != RecordTypeHashPostFeedPost {
		return fmt.Errorf("invalid record type: %s", post.Type)
	}
	
	if len(post.Text) == 0 {
		return fmt.Errorf("text is required")
	}
	
	if len(post.Text) > 3000 {
		return fmt.Errorf("text exceeds maximum length of 3000 characters")
	}
	
	return nil
}

// ValidateHashPostForumSubforum validates a HashPost forum subforum record
func ValidateHashPostForumSubforum(subforum *HashPostForumSubforum) error {
	if subforum.Type != RecordTypeHashPostForumSubforum {
		return fmt.Errorf("invalid record type: %s", subforum.Type)
	}
	
	if len(subforum.Name) == 0 {
		return fmt.Errorf("name is required")
	}
	
	if len(subforum.Name) > 100 {
		return fmt.Errorf("name exceeds maximum length of 100 characters")
	}
	
	if len(subforum.Slug) == 0 {
		return fmt.Errorf("slug is required")
	}
	
	// Validate slug format (alphanumeric + hyphens)
	for _, r := range subforum.Slug {
		if !((r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '-') {
			return fmt.Errorf("slug contains invalid characters: %s", subforum.Slug)
		}
	}
	
	if len(subforum.Description) > 500 {
		return fmt.Errorf("description exceeds maximum length of 500 characters")
	}
	
	return nil
}

// ValidateHashPostFeedComment validates a HashPost feed comment record
func ValidateHashPostFeedComment(comment *HashPostFeedComment) error {
	if comment.Type != RecordTypeHashPostFeedComment {
		return fmt.Errorf("invalid record type: %s", comment.Type)
	}
	
	if len(comment.Text) == 0 {
		return fmt.Errorf("text is required")
	}
	
	if len(comment.Text) > 3000 {
		return fmt.Errorf("text exceeds maximum length of 3000 characters")
	}
	
	if len(comment.Post) == 0 {
		return fmt.Errorf("post is required")
	}
	
	return nil
}
EOF

echo "Generated Go types in internal/lexicons/generated/types.go"
echo "Lexicon generation complete!"
